5: import { apiFetch } from "./apiClient";
6: import { buildQueryParams } from "./config";
7: import type { NewsItem, NewsCategory, NewsTag, NewsListResponse } from "@/types/news";
8: 
9: /**
10:  * 获取资讯列表
11:  */
12: export async function getNewsList(params?: {
13:   page?: number;
14:   page_size?: number;
15:   keyword?: string;
16:   start_date?: string;
17:   end_date?: string;
18:   report_type?: string;
19:   filter_type?: string;
20:   category_id?: number;
21:   tag_id?: number;
22: }): Promise<NewsListResponse> {
23:   const queryString = buildQueryParams({
24:     page: params?.page || 1,
25:     page_size: params?.page_size || 20,
26:     keyword: params?.keyword,
27:     start_date: params?.start_date,
28:     end_date: params?.end_date,
29:     report_type: params?.report_type,
30:     filter_type: params?.filter_type,
31:     category_id: params?.category_id,
32:     tag_id: params?.tag_id,
33:   });
34:   return apiFetch<NewsListResponse>(`/api/v1/news${queryString}`);
35: }
